  "rationale": "The Malaysian answer and English cue are sound, but Indonesian “tengara” means “sign” or “omen,” not a recognizable navigational landmark. The proposed contrast is therefore invalid and creates a false-friend risk.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Correct: “landmark” can mean a recognizable feature used for navigation.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=371752&keyword=landmark"
      ]
    },
    {
      "subject": "Indonesian answer: tengara",
      "conclusion": "Incorrect for this sense: Indonesian “tengara” means a sign, indication, or omen, not a landmark.",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.web.id/tengara",
        "https://baru.kbbi.co.id/arti-kata/tengara"
      ]
    },
    {
      "subject": "Malaysian answer: mercu tanda",
      "conclusion": "Correct: “mercu tanda” denotes an easily recognized object used as a guide to locate a place.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=mercu%20tanda"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "Incorrect: this is not a valid Indonesian-versus-Malaysian different-common-word pair because the Indonesian entry does not match the cue.",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.web.id/tengara",
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=mercu%20tanda"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "Material false-friend risk: learners may infer that Indonesian “tengara” corresponds to Malay “mercu tanda,” although its Indonesian meaning is different.",
      "material_risk": true,
      "evidence_refs": [
        "https://kbbi.web.id/tengara",
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=mercu%20tanda"
      ]
    }
  ]
}
